-- SHERIVS-UX1: dynamic per-user workspace manifest.
-- The workspace (nav, home widgets, quick actions, inbox streams) is computed on the server for every
-- request from: the caller's catalog roles (multi-role) -> role families -> default layout; effective
-- permissions (mandatory + admin-toggled optional + custom grants, or the legacy role bridge);
-- scope sets (shown as chips, enforced by authz_check / RLS on the data itself); the school's plan
-- features and enabled modules; and finally the user's own personalisation, which can only reference
-- items they are allowed to see. Hiding an item is presentation only: every data RPC/RLS policy keeps
-- enforcing the permission. workspace_item_allowed() is exported for data RPCs that want the same rule.
-- Rollback: database/supabase/rollbacks/20261025100210_sherivs_ux1_workspace_manifest.sql
BEGIN;

CREATE TABLE IF NOT EXISTS public.workspace_item_catalog (
  key text PRIMARY KEY,
  kind text NOT NULL CHECK (kind IN ('nav','widget','action','inbox')),
  route text NOT NULL,
  any_permissions text[] NOT NULL DEFAULT '{}',   -- at least one required (empty = everyone signed in)
  all_permissions text[] NOT NULL DEFAULT '{}',   -- every one required
  feature text,                                   -- plan feature or school module; NULL = always
  size text NOT NULL DEFAULT 'm' CHECK (size IN ('s','m','l')),
  label_en text NOT NULL,
  families text[] NOT NULL DEFAULT '{}',
  sort int NOT NULL DEFAULT 0);      -- presentation filter only (e.g. "My results" for students); empty = any family
CREATE TABLE IF NOT EXISTS public.workspace_family_layouts (
  family text PRIMARY KEY,
  template_codes text[] NOT NULL DEFAULT '{}',
  priority int NOT NULL,
  widgets text[] NOT NULL DEFAULT '{}',
  actions text[] NOT NULL DEFAULT '{}');
-- School module switches (absent row = module on). Plan features come from org_entitlements.
CREATE TABLE IF NOT EXISTS public.org_workspace_features (
  org_id uuid NOT NULL REFERENCES public.schools(id) ON DELETE CASCADE,
  feature text NOT NULL CHECK (feature ~ '^[a-z_]{2,32}$'),
  enabled boolean NOT NULL,
  updated_by uuid, updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (org_id, feature));
CREATE TABLE IF NOT EXISTS public.user_workspace_prefs (
  user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  org_id uuid NOT NULL REFERENCES public.schools(id) ON DELETE CASCADE,
  prefs jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(prefs) = 'object' AND pg_column_size(prefs) < 8192),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, org_id));

ALTER TABLE public.workspace_item_catalog ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.workspace_family_layouts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.org_workspace_features ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_workspace_prefs ENABLE ROW LEVEL SECURITY;
-- Track E posture (#120): RLS is FORCED on every public table.
ALTER TABLE public.workspace_item_catalog FORCE ROW LEVEL SECURITY;
ALTER TABLE public.workspace_family_layouts FORCE ROW LEVEL SECURITY;
ALTER TABLE public.org_workspace_features FORCE ROW LEVEL SECURITY;
ALTER TABLE public.user_workspace_prefs FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS workspace_item_catalog_read ON public.workspace_item_catalog;
CREATE POLICY workspace_item_catalog_read ON public.workspace_item_catalog FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS workspace_family_layouts_read ON public.workspace_family_layouts;
CREATE POLICY workspace_family_layouts_read ON public.workspace_family_layouts FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS org_workspace_features_read ON public.org_workspace_features;
CREATE POLICY org_workspace_features_read ON public.org_workspace_features FOR SELECT TO authenticated
  USING (org_id = (SELECT public.get_my_school_id()) OR (SELECT public.can_administer_org(org_id)));
DROP POLICY IF EXISTS user_workspace_prefs_own ON public.user_workspace_prefs;
CREATE POLICY user_workspace_prefs_own ON public.user_workspace_prefs FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
REVOKE INSERT, UPDATE, DELETE ON public.workspace_item_catalog, public.workspace_family_layouts,
  public.org_workspace_features, public.user_workspace_prefs FROM anon, authenticated;
GRANT SELECT ON public.workspace_item_catalog, public.workspace_family_layouts, public.org_workspace_features, public.user_workspace_prefs TO authenticated;

