  ('teacher',ARRAY['teacher','teaching_support','lab_workshop','early_years_carer','siwes','research']::text[],60,ARRAY['w.today_classes','w.attendance_todo','w.grading_queue','w.lesson_note_status','w.cbt_sessions','w.ai_lesson_helper','w.announcements']::text[],ARRAY['a.take_attendance','a.enter_scores','a.submit_note','a.new_cbt','a.request_leave']::text[]),
  ('hr',ARRAY['hr','payroll']::text[],35,ARRAY['w.payroll_run','w.staff_attendance','w.leave_requests','w.announcements']::text[],ARRAY['a.prepare_payroll','a.approve_payroll']::text[]),
  ('nurse',ARRAY['health','counsellor','chaplaincy']::text[],70,ARRAY['w.sick_bay','w.at_risk','w.announcements']::text[],ARRAY['a.log_visit']::text[]),
  ('librarian',ARRAY['librarian','library_staff']::text[],72,ARRAY['w.library_loans','w.announcements']::text[],ARRAY['a.issue_book']::text[]),
  ('hostel',ARRAY['hostel_head','house_staff']::text[],74,ARRAY['w.hostel_roll','w.hostel_beds','w.sick_bay','w.announcements']::text[],ARRAY['a.roll_call']::text[]),
  ('transport',ARRAY['transport_head','driver']::text[],76,ARRAY['w.my_trip','w.bus_live','w.announcements']::text[],ARRAY['a.start_trip']::text[]),
  ('security',ARRAY['security_head','security_staff']::text[],78,ARRAY['w.gate_log','w.incidents']::text[],ARRAY['a.sign_in_visitor','a.report_incident']::text[]),
  ('parent',ARRAY['parent','pta']::text[],90,ARRAY['w.children_summary','w.child_fees','w.child_bus','w.announcements']::text[],ARRAY['a.pay_fees']::text[]),
  ('student',ARRAY['student','student_leader','alumni']::text[],95,ARRAY['w.my_timetable','w.my_results','w.my_cbt','w.ai_tutor','w.announcements']::text[],ARRAY['a.ask_tutor']::text[]),
  ('gov',ARRAY['regulator','regulator_inspector']::text[],5,ARRAY['w.gov_overview','w.gov_compliance']::text[],ARRAY['a.gov_inspect']::text[]),
  ('staff',ARRAY[]::text[],99,ARRAY['w.announcements']::text[],ARRAY['a.request_leave']::text[])
ON CONFLICT (family) DO UPDATE SET template_codes=EXCLUDED.template_codes, priority=EXCLUDED.priority, widgets=EXCLUDED.widgets, actions=EXCLUDED.actions;
-- <<< generated <<<

-- Features: plan features (core, sms, whatsapp, ai, voice, codegen) + school modules ---------------
CREATE OR REPLACE FUNCTION public.workspace_features(p_org uuid) RETURNS text[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  WITH plan AS (
    SELECT coalesce((SELECT p.features FROM public.org_entitlements e JOIN public.entitlement_plans p ON p.id = e.plan_id WHERE e.org_id = p_org),
                    (SELECT features FROM public.entitlement_plans WHERE id = 'starter'), ARRAY['core']) f),
  modules AS (SELECT unnest(ARRAY['cbt','wallet','payroll','library','hostel','health','transport']) m)
  SELECT array(SELECT DISTINCT x FROM (
      SELECT unnest(f) x FROM plan
      UNION SELECT m FROM modules WHERE NOT EXISTS (SELECT 1 FROM public.org_workspace_features o WHERE o.org_id = p_org AND o.feature = m AND NOT o.enabled)
      UNION SELECT feature FROM public.org_workspace_features WHERE org_id = p_org AND enabled) s
    WHERE NOT EXISTS (SELECT 1 FROM public.org_workspace_features o WHERE o.org_id = p_org AND o.feature = s.x AND NOT o.enabled
                       AND s.x IN ('cbt','wallet','payroll','library','hostel','health','transport'))
    ORDER BY 1);
$$;

-- Legacy role bridge, set-based. Mirrors scholar_can()'s CASE for callers with no catalog role (calling
-- scholar_can once per code cost ~55 ms per manifest). The sim scenario "legacy bridge parity" fails if they drift.
CREATE OR REPLACE FUNCTION public._workspace_legacy_codes(p_role text) RETURNS text[]
LANGUAGE sql STABLE SET search_path = '' AS $$
  SELECT coalesce(array_agg(code ORDER BY code), '{}') FROM public.permission_catalog
   WHERE code NOT IN ('payroll.approve', 'audit.view', 'roles.assign', 'roles.configure', 'malpractice.decide')
     AND CASE
       WHEN p_role IN ('admin', 'principal') THEN true
       WHEN p_role = 'bursar' THEN code ~ '^(fees|payments|wallet|expenses|budget|payroll\.prepare|reports\.financial|procurement\.request|inventory|assets)'
       WHEN p_role = 'teacher' THEN code IN ('attendance.take', 'attendance.view', 'grades.enter', 'grades.view', 'exams.invigilate', 'lesson_notes.submit',
                                             'timetable.view', 'students.view', 'comms.send_class', 'cbt.manage', 'hr.leave_request', 'payroll.view_own', 'self.view_own')
       WHEN p_role IN ('parent', 'student') THEN code IN ('self.view_own', 'children.view', 'ai_tutor.use', 'timetable.view')
       ELSE false END;
$$;

-- Effective permission codes for the caller (catalog roles, or the legacy role bridge) ----------
CREATE OR REPLACE FUNCTION public.workspace_permission_codes(p_org uuid) RETURNS text[]
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE v text[];
BEGIN
  IF auth.uid() IS NULL THEN RETURN '{}'; END IF;
  SELECT array_agg(permission_code) INTO v FROM public.effective_permissions(p_org, auth.uid());
  IF v IS NULL AND (coalesce(public.is_super_admin(), false) OR public.get_my_school_id() IS NOT DISTINCT FROM p_org) THEN
    v := public._workspace_legacy_codes(CASE WHEN coalesce(public.is_super_admin(), false) THEN 'admin' ELSE public.get_my_role() END);
  END IF;
  RETURN coalesce(v, '{}');
END $$;

CREATE OR REPLACE FUNCTION public._workspace_item_ok(i public.workspace_item_catalog, p_perms text[], p_features text[], p_families text[] DEFAULT NULL) RETURNS boolean
LANGUAGE sql IMMUTABLE SET search_path = '' AS $$
  SELECT (cardinality(i.any_permissions) = 0 OR i.any_permissions && p_perms)
     AND (cardinality(i.families) = 0 OR p_families IS NULL OR i.families && p_families)
     AND i.all_permissions <@ p_perms
     AND (i.feature IS NULL OR i.feature = ANY (p_features));
$$;

CREATE OR REPLACE FUNCTION public.workspace_item_allowed(p_org uuid, p_key text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT coalesce((SELECT public._workspace_item_ok(i, public.workspace_permission_codes(p_org), public.workspace_features(p_org))
                     FROM public.workspace_item_catalog i WHERE i.key = p_key), false);
$$;

-- The manifest --------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.workspace_manifest(p_org uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_org uuid := coalesce(p_org, public.get_my_school_id());
  v_uid uuid := auth.uid();
  v_perms text[]; v_feat text[]; v_templates text[]; v_fams jsonb; v_prefs jsonb; v_hidden text[]; v_order text[];
  v_widgets text[]; v_actions text[]; v_out jsonb; v_legacy text; v_famarr text[];
BEGIN
  IF v_uid IS NULL OR v_org IS NULL THEN RAISE EXCEPTION 'not signed in' USING ERRCODE = '42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.user_role_assignments WHERE org_id = v_org AND user_id = v_uid AND status = 'active')
     AND public.get_my_school_id() IS DISTINCT FROM v_org AND NOT coalesce(public.is_super_admin(), false) THEN
    RAISE EXCEPTION 'not a member of this organisation' USING ERRCODE = '42501';
  END IF;
  v_perms := public.workspace_permission_codes(v_org);
  v_feat := public.workspace_features(v_org);
  SELECT array_agg(DISTINCT r.template_code) INTO v_templates
    FROM public.user_role_assignments a JOIN public.role_catalog r ON r.code = a.role_code
   WHERE a.org_id = v_org AND a.user_id = v_uid AND a.status = 'active';
  IF v_templates IS NULL THEN
    v_legacy := public.get_my_role();
    v_templates := ARRAY[CASE v_legacy WHEN 'admin' THEN 'head_of_institution' WHEN 'principal' THEN 'head_of_institution'
      WHEN 'bursar' THEN 'bursar' WHEN 'teacher' THEN 'teacher' WHEN 'parent' THEN 'parent' WHEN 'student' THEN 'student' ELSE 'support_staff' END];
  END IF;
  SELECT coalesce(jsonb_agg(f.family ORDER BY f.priority), '["staff"]') INTO v_fams
    FROM public.workspace_family_layouts f WHERE f.template_codes && v_templates;
  IF jsonb_array_length(v_fams) = 0 THEN v_fams := '["staff"]'; END IF;
  v_famarr := array(SELECT jsonb_array_elements_text(v_fams));
  SELECT prefs INTO v_prefs FROM public.user_workspace_prefs WHERE user_id = v_uid AND org_id = v_org;
  v_prefs := coalesce(v_prefs, '{}');
  v_hidden := array(SELECT jsonb_array_elements_text(coalesce(v_prefs->'hidden', '[]')));
  v_order := array(SELECT jsonb_array_elements_text(coalesce(v_prefs->'order', '[]')));

  WITH ok AS (SELECT i.* FROM public.workspace_item_catalog i WHERE public._workspace_item_ok(i, v_perms, v_feat, v_famarr)),
  fam AS (SELECT f.*, ord FROM public.workspace_family_layouts f
            JOIN jsonb_array_elements_text(v_fams) WITH ORDINALITY x(fam, ord) ON x.fam = f.family),
  cand AS (
    SELECT k, min(ord * 1000 + pos) base FROM (
      SELECT w k, fam.ord, pos FROM fam, unnest(fam.widgets) WITH ORDINALITY u(w, pos)
      UNION ALL SELECT e, 999, pos FROM jsonb_array_elements_text(coalesce(v_prefs->'added', '[]')) WITH ORDINALITY u(e, pos)) z
    GROUP BY k)
  SELECT array_agg(c.k ORDER BY coalesce(array_position(v_order, c.k), 100000 + c.base)) INTO v_widgets
    FROM cand c JOIN ok ON ok.key = c.k AND ok.kind = 'widget' WHERE NOT (c.k = ANY (v_hidden));

  WITH ok AS (SELECT i.* FROM public.workspace_item_catalog i WHERE public._workspace_item_ok(i, v_perms, v_feat, v_famarr) AND i.kind = 'action'),
  pref AS (SELECT e k, pos FROM jsonb_array_elements_text(coalesce(v_prefs->'actions', '[]')) WITH ORDINALITY u(e, pos)),
  dflt AS (SELECT a k, min(x.ord * 1000 + pos) pos FROM public.workspace_family_layouts f
             JOIN jsonb_array_elements_text(v_fams) WITH ORDINALITY x(fam, ord) ON x.fam = f.family,
             unnest(f.actions) WITH ORDINALITY u(a, pos) GROUP BY a),
  src AS (SELECT * FROM pref UNION ALL SELECT * FROM dflt WHERE NOT EXISTS (SELECT 1 FROM pref))
  SELECT (array_agg(src.k ORDER BY src.pos))[1:6] INTO v_actions FROM src JOIN ok ON ok.key = src.k;

  SELECT jsonb_build_object(
    'version', 1, 'org_id', v_org, 'families', v_fams, 'primary_family', v_fams->>0, 'features', to_jsonb(v_feat),
    'locale', coalesce(v_prefs->>'locale', 'en'), 'density', coalesce(v_prefs->>'density', 'comfortable'),
    'scopes', coalesce((SELECT jsonb_agg(jsonb_build_object('role', a.role_code, 'type', a.scope_type, 'ref', a.scope_ref,
                 'sets', (SELECT coalesce(jsonb_agg(d.dims), '[]') FROM (SELECT (SELECT jsonb_object_agg(dim, refs) FROM (
                     SELECT dim, jsonb_agg(ref ORDER BY ref) refs FROM public.role_assignment_scopes WHERE set_id = ss.id GROUP BY dim) q) dims
                   FROM public.role_assignment_scope_sets ss WHERE ss.assignment_id = a.id) d)))
               FROM public.user_role_assignments a WHERE a.org_id = v_org AND a.user_id = v_uid AND a.status = 'active'), '[]'),
    'nav', coalesce((SELECT jsonb_agg(jsonb_build_object('key', key, 'to', route, 'label', label_en) ORDER BY sort)
                 FROM public.workspace_item_catalog i WHERE kind = 'nav' AND public._workspace_item_ok(i, v_perms, v_feat, v_famarr)), '[]'),
    'widgets', coalesce((SELECT jsonb_agg(jsonb_build_object('key', i.key, 'to', i.route, 'size', i.size, 'label', i.label_en) ORDER BY u.pos)
                 FROM unnest(v_widgets) WITH ORDINALITY u(k, pos) JOIN public.workspace_item_catalog i ON i.key = u.k), '[]'),
    'available', coalesce((SELECT jsonb_agg(i.key ORDER BY i.sort) FROM public.workspace_item_catalog i
                 WHERE i.kind = 'widget' AND public._workspace_item_ok(i, v_perms, v_feat, v_famarr) AND NOT (i.key = ANY (coalesce(v_widgets, '{}')))), '[]'),
    'actions', coalesce((SELECT jsonb_agg(jsonb_build_object('key', i.key, 'to', i.route, 'label', i.label_en) ORDER BY u.pos)
                 FROM unnest(v_actions) WITH ORDINALITY u(k, pos) JOIN public.workspace_item_catalog i ON i.key = u.k), '[]'),
    'inbox', coalesce((SELECT jsonb_agg(jsonb_build_object('key', key, 'to', route, 'label', label_en) ORDER BY sort)
                 FROM public.workspace_item_catalog i WHERE kind = 'inbox' AND public._workspace_item_ok(i, v_perms, v_feat, v_famarr)), '[]'),
    'hidden_by_policy', (SELECT count(*) FROM public.workspace_item_catalog i WHERE NOT public._workspace_item_ok(i, v_perms, v_feat, v_famarr))
  ) INTO v_out;
  RETURN v_out;
END $$;

-- Personalisation: only allowed items can be stored ----------------------------------------------
CREATE OR REPLACE FUNCTION public.workspace_prefs_save(p_org uuid, p_prefs jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_perms text[]; v_feat text[]; v_clean jsonb; v_keys text[];
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not signed in' USING ERRCODE = '42501'; END IF;
  PERFORM public.workspace_manifest(p_org);  -- membership check
  v_perms := public.workspace_permission_codes(p_org); v_feat := public.workspace_features(p_org);
  SELECT array_agg(key) INTO v_keys FROM public.workspace_item_catalog i WHERE public._workspace_item_ok(i, v_perms, v_feat);
  v_keys := coalesce(v_keys, '{}');
  v_clean := jsonb_strip_nulls(jsonb_build_object(
    'order', (SELECT jsonb_agg(e) FROM jsonb_array_elements_text(coalesce(p_prefs->'order', '[]')) e WHERE e = ANY (v_keys) AND e LIKE 'w.%'),
    'hidden', (SELECT jsonb_agg(e) FROM jsonb_array_elements_text(coalesce(p_prefs->'hidden', '[]')) e WHERE e = ANY (v_keys) AND e LIKE 'w.%'),
    'added', (SELECT jsonb_agg(e) FROM jsonb_array_elements_text(coalesce(p_prefs->'added', '[]')) e WHERE e = ANY (v_keys) AND e LIKE 'w.%'),
    'actions', (SELECT jsonb_agg(e) FROM (SELECT e FROM jsonb_array_elements_text(coalesce(p_prefs->'actions', '[]')) e WHERE e = ANY (v_keys) AND e LIKE 'a.%' LIMIT 6) q),
    'locale', CASE WHEN p_prefs->>'locale' IN ('en','ha','yo','ig','pcm') THEN p_prefs->'locale' END,
    'density', CASE WHEN p_prefs->>'density' IN ('comfortable','compact') THEN p_prefs->'density' END));
  INSERT INTO public.user_workspace_prefs (user_id, org_id, prefs) VALUES (auth.uid(), p_org, v_clean)
  ON CONFLICT (user_id, org_id) DO UPDATE SET prefs = EXCLUDED.prefs, updated_at = now();
  RETURN v_clean;
END $$;

CREATE OR REPLACE FUNCTION public.workspace_feature_set(p_org uuid, p_feature text, p_enabled boolean) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF NOT public.scholar_can(p_org, 'settings.manage') THEN RAISE EXCEPTION 'settings.manage required' USING ERRCODE = '42501'; END IF;
  IF p_feature NOT IN ('cbt','wallet','payroll','library','hostel','health','transport') THEN
    RAISE EXCEPTION 'unknown module %', p_feature USING ERRCODE = '22023'; END IF;
  INSERT INTO public.org_workspace_features (org_id, feature, enabled, updated_by) VALUES (p_org, p_feature, p_enabled, auth.uid())
  ON CONFLICT (org_id, feature) DO UPDATE SET enabled = EXCLUDED.enabled, updated_by = EXCLUDED.updated_by, updated_at = now();
END $$;

REVOKE ALL ON FUNCTION public.workspace_features(uuid), public.workspace_permission_codes(uuid), public._workspace_legacy_codes(text),
  public._workspace_item_ok(public.workspace_item_catalog, text[], text[], text[]), public.workspace_item_allowed(uuid, text),
  public.workspace_manifest(uuid), public.workspace_prefs_save(uuid, jsonb), public.workspace_feature_set(uuid, text, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.workspace_features(uuid), public.workspace_item_allowed(uuid, text), public.workspace_manifest(uuid),
  public.workspace_prefs_save(uuid, jsonb), public.workspace_feature_set(uuid, text, boolean) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public._workspace_legacy_codes(text), public.workspace_permission_codes(uuid), public._workspace_item_ok(public.workspace_item_catalog, text[], text[], text[]) TO service_role;
COMMIT;
